//! Start-value, presample-with-X, and Display vs Options.Display tests.
//! Reference fixture generated by: bash tool/ref-python.sh tool/refs/econ/start.py
use matrust::{Array, Engine, Matrix};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/econ/start.json")).unwrap()
}

fn run(e: &mut Engine, source: &str) {
    e.execute(source)
        .unwrap_or_else(|err| panic!("{source}: {err}"));
}

fn values(e: &Engine, name: &str) -> Vec<f64> {
    match e.array(name).unwrap() {
        Array::Numeric(m) => m.data().to_vec(),
        a => panic!("{name}: {a:?}"),
    }
}

fn data(e: &mut Engine, c: &Value) {
    let y: Vec<_> = c["y"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect();
    e.insert_array(
        "y",
        Array::Numeric(Matrix::from_column_vec(y.len(), 1, y).unwrap()),
    )
    .unwrap();
}

#[test]
fn seeded_infeasible_heuristic_starts_now_estimate_and_match_statsmodels() {
    let refs = fixture();
    let specs = [
        (
            "ar10_ma1",
            11u64,
            "arima('ARLags',1:10,'MALags',1,'Constant',0)",
            ",Y0=zeros(10,1),E0=0",
        ),
        (
            "ma2_fixed",
            22u64,
            "arima('MALags',[1 2],'MA',{NaN -0.9},'Constant',0)",
            ",E0=[0;0]",
        ),
        (
            "arima10_1_0",
            33u64,
            "arima('ARLags',1:10,'D',1,'Constant',0)",
            ",Y0=zeros(11,1)",
        ),
    ];
    for (idx, (name, seed, model, pre)) in specs.iter().enumerate() {
        let c = &refs["cases"][idx];
        assert_eq!(c["name"].as_str().unwrap(), *name);
        assert_eq!(c["seed"].as_u64().unwrap(), *seed);
        let ref_ll = c["ll"].as_f64().unwrap();
        let mut e = Engine::default();
        data(&mut e, c);
        run(
            &mut e,
            &format!("[f,cov,ll,info]=estimate({model},y,Display='off'{pre});x0=info.X0;x=info.X;"),
        );
        let ll = values(&e, "ll")[0];
        assert!(
            ll >= ref_ll - 1e-4,
            "{name} (seed {seed}): ll={ll} < ref_ll-1e-4 ({ref_ll})"
        );
        // Zero-iteration check confirms the automatic start itself is strictly feasible.
        run(
            &mut e,
            &format!(
                "[f0,~,ll0]=estimate({model},y,Display='off',Options=optimset('MaxIter',0){pre});"
            ),
        );
        assert!(values(&e, "ll0")[0].is_finite());
    }
}

#[test]
fn egarch_fixed_garch_lag_shrinks_start_and_infeasible_user_starts_error() {
    let mut e = Engine::default();
    run(
        &mut e,
        "rng(7);y=simulate(egarch('GARCHLags',[1 2],'GARCH',{0.9 0.05},'ARCH',0.1,'Leverage',-0.05,'Constant',-0.1),300);",
    );
    // Today's initial_model put 0.8 in GARCH{2} alongside fixed 0.9, violating stationarity.
    run(
        &mut e,
        "m=egarch('GARCHLags',[1 2],'GARCH',{0.9 NaN},'ARCH',NaN,'Leverage',NaN);[f,~,ll]=estimate(m,y,Display='off',Options=optimset('MaxIter',0));assert(isfinite(ll));",
    );
    for (cmd, msg) in [
        (
            "estimate(arima(1,0,0),y,AR0=1.05,Display='off')",
            "stationary",
        ),
        (
            "estimate(arima(0,0,1),y,MA0=-1.05,Display='off')",
            "invertible",
        ),
        (
            "estimate(garch(1,1),y,GARCH0=0.8,ARCH0=0.3,Display='off')",
            "InvalidParameter",
        ),
    ] {
        let err = e.execute(cmd).unwrap_err();
        assert!(
            err.contains(msg) || err.contains("Invalid") || err.contains("Non"),
            "{cmd}: {err}"
        );
    }
}

#[test]
fn presample_with_x_and_without_y0_uses_first_p_observations() {
    // MathWorks arima.estimate doc: when Y0 is not specified with exogenous predictors X,
    // responses cannot be backcast from unavailable presample predictors; MatRust keeps the
    // documented rule ("With X and no Y0, the first P responses are the presample, so the
    // effective sample is P observations shorter.") and aligns X to the remaining T - P rows.
    let mut e = Engine::default();
    run(
        &mut e,
        "rng(42);x=randn(60,1);e=0.5*randn(60,1);y=zeros(60,1);for t=2:60,y(t)=0.5*y(t-1)+1.2*x(t)+e(t);end",
    );
    run(
        &mut e,
        "m=arima(Constant=0,AR=NaN,Beta=NaN);[f1,c1,ll1,i1]=estimate(m,y,X=x,Display='off');[f2,c2,ll2,i2]=estimate(m,y(2:end),Y0=y(1),X=x(2:end),Display='off');p1=i1.X;p2=i2.X;s1=summarize(f1);",
    );
    let ll1 = values(&e, "ll1")[0];
    let ll2 = values(&e, "ll2")[0];
    assert!((ll1 - ll2).abs() < 1e-10, "ll1={ll1} != ll2={ll2}");
    let p1 = values(&e, "p1");
    let p2 = values(&e, "p2");
    for (a, b) in p1.iter().zip(&p2) {
        assert!((a - b).abs() < 1e-8, "{a} != {b}");
    }
    run(&mut e, "assert(s1.SampleSize==59);");
}

#[test]
fn display_controls_report_while_options_display_only_controls_optimizer() {
    let mut e = Engine::default();
    run(
        &mut e,
        "rng(101);y=simulate(arima(Constant=0.2,AR=0.5,Variance=0.8),120);",
    );

    // 1. Display='off' prints nothing, even if Options.Display='iter'.
    let out_off = e
        .execute("o_iter=optimoptions(@fmincon,'Display','iter');f_off=estimate(arima(1,0,0),y,Y0=0,Display='off',Options=o_iter);")
        .unwrap();
    assert!(
        out_off.output.is_empty(),
        "Display='off' should emit nothing, got: {:?}",
        out_off.output
    );

    // 2. Options.Display='off' with default Display still prints the parameter report table.
    let out_opt_off = e
        .execute("o_off=optimoptions(@fmincon,'Display','off');[f_def,~,~,info_def]=estimate(arima(1,0,0),y,Y0=0,Options=o_off);ar_val=f_def.AR{1};")
        .unwrap();
    let text = out_opt_off.output.join("\n");
    assert!(
        text.contains("AR{1}") && text.contains("Constant"),
        "Expected parameter report table when Options.Display='off', got:\n{text}"
    );
    assert!(
        !text.contains("Iter ") && !text.contains("f(x)"),
        "Options.Display='off' should suppress optimizer iterations, got:\n{text}"
    );
    let ar_val = values(&e, "ar_val")[0];
    let ar_str = format!("{ar_val:.4}");
    assert!(
        text.contains(&ar_str[..5]),
        "Expected printed report to contain AR{{1}} value ~{ar_str}, got:\n{text}"
    );

    // 3. Same separation for garch: Display='off' prints nothing; Options.Display='off' still prints table.
    run(
        &mut e,
        "rng(102);yg=simulate(garch(Constant=0.05,GARCH=0.7,ARCH=0.2),200);",
    );
    let gout_off = e
        .execute("gf_off=estimate(garch(1,1),yg,Display='off',Options=o_iter);")
        .unwrap();
    assert!(
        gout_off.output.is_empty(),
        "GARCH Display='off' should emit nothing, got: {:?}",
        gout_off.output
    );
    let gout_opt_off = e
        .execute("[gf_def,~,g_ll]=estimate(garch(1,1),yg,Options=o_off);")
        .unwrap();
    let gtext = gout_opt_off.output.join("\n");
    assert!(
        gtext.contains("GARCH(1,1) Conditional Variance Model") && gtext.contains("LogLikelihood:"),
        "Expected GARCH report when Options.Display='off', got:\n{gtext}"
    );
    let g_ll = values(&e, "g_ll")[0];
    let g_ll_str = format!("{g_ll:.4}");
    assert!(
        gtext.contains(&g_ll_str[..5]),
        "Expected printed GARCH report to contain LogLikelihood ~{g_ll_str}, got:\n{gtext}"
    );
}
